import cProfile,json,tempfile
from pathlib import Path
from aluclu.cognition.persistence import _is_link_or_reparse
root=Path(tempfile.mkdtemp(prefix="alc-r0-metadata-count-"))
path=root/"regular"
with path.open("xb") as stream: stream.write(b"x")
def baseline(path):
    try: metadata=path.lstat()
    except FileNotFoundError: return False
    if path.is_symlink(): return True
    return bool(getattr(metadata,"st_file_attributes",0)&0x400)
for name,helper in (("reconstructed-baseline",baseline),("current",_is_link_or_reparse)):
    profile=cProfile.Profile()
    profile.enable()
    for i in range(32):
        if helper(path) is not False: raise RuntimeError("regular path misclassified")
    profile.disable()
    entries=[dict(code=item.code,calls=item.callcount) for item in profile.getstats() if isinstance(item.code,str) and "nt.stat" in item.code]
    print(json.dumps(dict(scope="native-stat-count-only-not-walltime-benchmark",name=name,helper_calls=32,native_stat_entries=entries,native_stat_calls=sum(item["calls"] for item in entries),namespace=str(root),profile_overhead=True),sort_keys=True),flush=True)
